import sys

MIN, MAX = -(1 << 63), (1 << 63) - 1

def decimal(text):
    digits = text[1:] if text.startswith("-") else text
    if not digits.isascii() or not digits.isdecimal():
        return None
    if len(digits) <= 19:
        value = int(text)
    else:
        digits = digits.lstrip("0") or "0"
        if len(digits) > 19:
            return None
        value = int(digits) * (-1 if text.startswith("-") else 1)
    return value if MIN <= value <= MAX else None

def degree_hours(initial, readings):
    total = initial
    for temperature in readings:
        if temperature < 18:
            deficit = 18 - temperature
            if deficit > MAX:
                raise OverflowError
            total += deficit
            if total > MAX:
                raise OverflowError
    return total

def main(args):
    if not args:
        return '{"code":"E_INPUT","reason":"missing_seed"}'
    if len(args) > 4097:
        return '{"code":"E_INPUT","reason":"list_too_long","limit":4096}'
    numbers = []
    for index, token in enumerate(args, 1):
        value = decimal(token)
        if value is None:
            return '{"code":"E_INPUT","reason":"expected_i64","argument":%d}' % index
        numbers.append(value)
    try:
        values = iter(numbers)
        print(degree_hours(next(values), values))
    except OverflowError:
        return '{"code":"E_OVERFLOW"}'

if __name__ == "__main__":
    error = main(sys.argv[1:])
    if error is not None:
        print(error, file=sys.stderr)
        sys.exit(1)

