import hashlib, json, math, os, platform, random, shutil, statistics, subprocess, sys, time
from pathlib import Path

repo=Path.cwd().resolve()
w=Path(sys.argv[1]).resolve()
cpu=2
os.sched_setaffinity(0,{cpu})
native=w/'heating'
src=w/'program.tide'
cpy=[sys.executable,'-BS',str(w/'comparator.py')]
w.mkdir(exist_ok=True)
shutil.copyfile(repo/'apps/heating.tide',src)
shutil.copyfile(repo/'tide.lock',w/'tide.lock')
def hashfile(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def build():
    begin=time.perf_counter_ns()
    subprocess.run([repo/'tide','check',src],capture_output=True,check=True)
    data=subprocess.run([repo/'tide','run',repo/'native/fold_i64.tide','--call','compile_entry','--read','source='+str(src),'--inputs','{"entry":"degree_hours"}'],capture_output=True,check=True)
    native.write_bytes(bytes.fromhex(json.loads(data.stdout))); native.chmod(0o700)
    return time.perf_counter_ns()-begin
builds=[]; hashes=set()
for n in range(12):
    ns=build(); hashes.add(hashfile(native))
    if n>=2: builds.append(ns)
assert len(hashes)==1
def timer(cmd,expected):
    start=time.perf_counter_ns()
    p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    ns=time.perf_counter_ns()-start
    assert (p.returncode,p.stdout,p.stderr)==(0,expected,b''),(cmd[:2],p.returncode,p.stderr,p.stdout)
    return ns
def stats(rows):
    def sample(x):
        y=sorted(x)
        return {'median':statistics.median(y),'p95_nearest_rank':y[math.ceil(.95*len(y))-1],'min':y[0],'max':y[-1]}
    return {k:sample([r[k] for r in rows]) for k in ['native_ns','cpython_ns','paired_ratio']}
rows=[]; summary={}
for n in [0,16,4096]:
    group=[]
    for repetition in range(-6,30):
        rng=random.Random(210000+100*n+repetition)
        initial=rng.randrange(-100000,100001)
        readings=[rng.randrange(-18,43) for i in range(n)]
        args=[str(initial),*map(str,readings)]
        params=json.dumps({'initial':initial,'readings':readings},separators=(',',':'))
        expected=subprocess.run([repo/'tide','run',src,'--call','degree_hours','--inputs',params],capture_output=True,check=True).stdout
        commands={'native':[str(native),*args],'cpython':cpy+args}
        order=['native','cpython'] if repetition%2==0 else ['cpython','native']
        timings={k:timer(commands[k],expected) for k in order}
        row={'n':n,'repetition':repetition,'start':order[0],'seed':210000+100*n+repetition,'value':int(expected),'argv_sha256':hashlib.sha256(json.dumps(args,separators=(',',':')).encode()).hexdigest(),'native_ns':timings['native'],'cpython_ns':timings['cpython'],'paired_ratio':timings['cpython']/timings['native']}
        rows.append(row)
        if repetition>=0: group.append(row)
    summary[n]=stats(group)
image={'size':native.stat().st_size,'sha256':hashfile(native),'readelf':subprocess.run(['readelf','-lW',native],check=True,capture_output=True,text=True).stdout}
assert image['sha256'] in hashes
result={'source_sha256':hashfile(src),'python_sha256':hashfile(w/'comparator.py'),'cpu':cpu,'cpu_model':next(l.split(':',1)[1].strip() for l in Path('/proc/cpuinfo').read_text().splitlines() if l.startswith('model name')),'governor':Path(f'/sys/devices/system/cpu/cpu{cpu}/cpufreq/scaling_governor').read_text().strip(),'python':platform.python_version(),'cpython_flags':'-BS','platform':platform.platform(),'ELF':image,'build_ns':builds,'build_median_ns':statistics.median(builds),'rows':rows,'summary':summary}
(w/'timings.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(summary))
